member.remarks:
To use this attribute, attach it to a method in a
 subclass.
Here is an example:

public class FooTest : TestCase {
  public ExpectExceptionTest(string Name) : base(Name) {}
  [ExpectException(typeof(ArgumentException))]
  [ExpectException(typeof(IndexOutOfRangeException))]
  public void TestBar() {
    throw new ArgumentException("bad argument");
  }
}

To use this attribute, attach it to a method in a
 subclass.
Here is an example:

public class FooTest : TestCase {
  public ExpectExceptionTest(string Name) : base(Name) {}
  [ExpectExceptionMessage(typeof(ArgumentException), "bad argument")]
  public void TestBar() {
    throw new ArgumentException("bad argument");
  }
}

To use this attribute, attach it to a method in a
 subclass.
Here is an example:

public class FooTest : TestCase {
  public ExpectNoExceptions(string Name) : base(Name) {}
  [ExpectNoExceptions()]
  public void TestBar() {
    DoSomeSillyThing();
  }
}
